# Long / Short Lab — standalone Streamlit app
# Upload this file as app.py to GitHub; no data folder or other source files needed.
# Deploy with app.py as the main file. Uses Streamlit, pandas and NumPy.
# Embedded dataset: reviewed 500-company snapshot from October 16, 2026.
# No API keys, live data requests, or external data files.
from io import StringIO
import base64
import zlib

EMBEDDED_DATA = ''

import argparse
import json
from pathlib import Path
import numpy as np
import pandas as pd

GROUPS = {
    'valuation': {'book_to_market_snapshot': True, 'earnings_yield_class_snapshot': True},
    'profitability': {'gpa': True, 'roc_after_tax': True, 'cfoa_class': True,
                      'margin_growth_rate': True, 'margin_stability': True},
    'earnings_quality': {'sta': False, 'snoa': False},
    'financial_strength': {'z_score_class': True, 'f_score_class_net_corrected_roa': True},
}
WEIGHTS = {group: .25 for group in GROUPS}


def percentile(series, higher_better=True):
    """Average tied ranks on 0..100 scale; larger score always more favorable."""
    if len(series) < 2:
        return pd.Series(np.nan, index=series.index)
    return (series.rank(method='average', ascending=higher_better)-1)/(len(series)-1)*100


def score(frame, tail=20, min_peers=5):
    if not 0 < tail < 50 or min_peers < 2:
        raise ValueError('Require 0 < tail < 50 and min_peers >= 2')
    df=frame.copy()
    # User-confirmed slide coefficients, with decimal X inputs.
    df['z_score_class']=sum(c*pd.to_numeric(df[f'z_x{i}'],errors='coerce')
                            for i,c in enumerate([.012,.014,.033,.006,.999],1))
    fields=[f for group in GROUPS.values() for f in group]
    for name in fields:
        df[name]=pd.to_numeric(df[name],errors='coerce').replace([np.inf,-np.inf],np.nan)
    reasons=[]
    for _,r in df.iterrows():
        why=[]
        if pd.isna(r['sector']) or not str(r['sector']).strip():
            why.append('sector unavailable')
        if r['sector'] in ['Financials','Financial Services']:
            why.append('financial company: separate model required')
        if pd.isna(r['statement_age_days']) or r['statement_age_days']>550 or r['statement_age_days']<0:
            why.append('annual statement stale or date unavailable')
        if pd.notna(r['book_to_market_snapshot']) and r['book_to_market_snapshot']<=0:
            why.append('nonpositive book equity: valuation requires review')
        missing=[f for f in fields if pd.isna(r[f])]
        if missing:
            why.append('missing required metrics: '+', '.join(missing))
        reasons.append('; '.join(why))
    df['eligibility_reason']=reasons
    df['metrics_available_for_scoring']=df[fields].notna().sum(axis=1)
    initial=df.eligibility_reason.eq('')
    df['eligible_sector_peers']=df['sector'].map(df.loc[initial].groupby('sector').size()).fillna(0).astype(int)
    small=initial & df.eligible_sector_peers.lt(min_peers)
    df.loc[small,'eligibility_reason']='too few eligible sector peers'
    df['eligible']=df.eligibility_reason.eq('')
    eligible=df.loc[df.eligible]
    for group,mapping in GROUPS.items():
        metric_scores=[]
        for metric,higher in mapping.items():
            col=metric+'_percentile'
            df[col]=np.nan
            df.loc[eligible.index,col]=eligible.groupby('sector')[metric].transform(
                lambda s: percentile(s,higher))
            metric_scores.append(col)
        df[group+'_score']=df[metric_scores].mean(axis=1,skipna=False)
    df['overall_score']=sum(df[g+'_score']*weight for g,weight in WEIGHTS.items())
    df['sector_composite_percentile']=np.nan
    df.loc[eligible.index,'sector_composite_percentile']=df.loc[eligible.index].groupby('sector')['overall_score'].transform(percentile)
    df['classification']='Not assigned'
    df.loc[df.eligible,'classification']='Neutral'
    df.loc[df.eligible & df.sector_composite_percentile.ge(100-tail),'classification']='Long candidate'
    df.loc[df.eligible & df.sector_composite_percentile.le(tail),'classification']='Short candidate'
    df['sector_rank']=np.nan
    df.loc[eligible.index,'sector_rank']=df.loc[eligible.index].groupby('sector').overall_score.rank(ascending=False,method='min')
    return df





METRICS = {
    'gpa': ('GPA (%)', 100., 'Higher is favorable'),
    'book_to_market_snapshot': ('Book-to-market', 1., 'Higher is favorable'),
    'earnings_yield_class_snapshot': ('Earnings yield (%)', 100., 'Higher is favorable'),
    'roc_after_tax': ('After-tax ROC (%)', 100., 'Higher is favorable'),
    'sta': ('STA (%)', 100., 'Lower is favorable'),
    'snoa': ('SNOA (%)', 100., 'Lower is favorable'),
    'z_score_class': ('Class Z-score', 1., 'Higher is favorable; class coefficients'),
    'f_score_class_net_corrected_roa': ('F-score', 1., 'Higher is favorable; 0–9'),
    'cfoa_class': ('CFOA (%)', 100., 'Cumulative FCF divided by ending assets'),
    'margin_growth_rate': ('Margin growth (%)', 100., 'Annual geometric growth'),
    'margin_stability': ('Margin stability', 1., 'Average gross margin / sample standard deviation'),
}
CLASSES = ['Long candidate', 'Short candidate', 'Neutral', 'Not assigned']


def run_screen(data, config):
    """Ranges, sector and search precede optional rerank; class/score follow it."""
    baseline = score(data, tail=config.get('tail',20))
    universe = baseline[baseline.sector.isin(config['sectors'])].copy()
    query = config.get('search','').strip()
    if query:
        matches = universe.ticker.fillna('').str.contains(query,case=False,regex=False)
        matches |= universe.company_name.fillna('').str.contains(query,case=False,regex=False)
        universe = universe[matches].copy()
    for metric, bounds in config.get('ranges',{}).items():
        universe = universe[universe[metric].between(bounds[0],bounds[1],inclusive='both')].copy()
    ranked = score(universe,tail=config.get('tail',20)) if config.get('rerank',False) and len(universe) else universe
    # Unassigned rows have no score. A positive minimum intentionally excludes them.
    view = ranked[ranked.classification.isin(config['classes'])].copy()
    minimum = config.get('min_score',0)
    if minimum > 0:
        view = view[view.overall_score.ge(minimum)].copy()
    view = view.sort_values(['overall_score','ticker'],ascending=[False,True],na_position='last')
    return view, ranked


